from collections import deque
from typing import List

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def createTree(parent: List[int], N: int) -> TreeNode:
    nodes = [TreeNode(i) for i in range(N)]
    root = None
    for i in range(N):
        if parent[i] == -1:
            root = nodes[i]
        else:
            p_node = nodes[parent[i]]
            if p_node.left is None:
                p_node.left = nodes[i]
            else:
                p_node.right = nodes[i]
    return root

def level_order_traversal(root: TreeNode) -> List[int]:
    result = []
    queue = deque([root])
    while queue:
        node = queue.popleft()
        result.append(node.val)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result

